306:func atomicWrite(path string, data []byte) error {
307:	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
308:		return err
309:	}
310:	temporary := fmt.Sprintf("%s.tmp-%d", path, os.Getpid())
311:	if err := os.WriteFile(temporary, data, 0o644); err != nil {
312:		return err
313:	}
314:	if err := os.Rename(temporary, path); err != nil {
315:		_ = os.Remove(temporary)
316:		return err
317:	}
318:	return nil
319:}
