203:func splitHandles(handles []string) (knowledgeHandles, codeHandles []string) {
204:	for _, handle := range handles {
205:		if strings.HasPrefix(handle, "knowledge://") {
206:			knowledgeHandles = append(knowledgeHandles, handle)
207:		} else {
