214:func useDocumentVectors(request Request) bool {
215:	return request.UseDocumentVectors != nil && *request.UseDocumentVectors
216:}
217:
218:func includeDocuments(request Request) bool {
219:	if request.CodeOnly {
220:		return false
221:	}
222:	if request.IncludeDocuments != nil {
223:		return *request.IncludeDocuments
224:	}
225:	return request.Mode == "orient" || request.Mode == "search"
