227:
228:func retrieveDocuments(ctx context.Context, request Request, statePath string, preparation repostate.Status, handles []string) ([]knowledge.Result, int, []string, error) {
229:	if !includeDocuments(request) && len(handles) == 0 {
230:		return nil, 0, nil, nil
231:	}
232:	knowledgeState := filepath.Join(statePath, "knowledge")
233:	current, loadErr := knowledge.Load(knowledgeState)
234:	rebuild := loadErr != nil || preparation.Knowledge.Status != "current"
235:	if rebuild {
236:		var previous *knowledge.Index
237:		if loadErr == nil {
238:			previous = &current
239:		} else if !errors.Is(loadErr, os.ErrNotExist) && !errors.Is(loadErr, knowledge.ErrIncompatibleIndex) {
240:			return nil, 0, nil, fmt.Errorf("load knowledge index: %w", loadErr)
241:		}
242:		built, _, err := knowledge.Build(request.Root, previous, knowledge.BuildOptions{})
243:		if err != nil {
244:			return nil, 0, nil, fmt.Errorf("build knowledge index: %w", err)
245:		}
246:		built.SourceFingerprint = preparation.Repository.SourceFingerprint
247:		if err := knowledge.Save(knowledgeState, built); err != nil {
248:			return nil, 0, nil, fmt.Errorf("save knowledge index: %w", err)
249:		}
250:		current = built
251:	}
252:
253:	results := make([]knowledge.Result, 0)
254:	for _, handle := range handles {
255:		value, err := knowledge.Inspect(current, "", handle)
256:		if err != nil {
257:			return nil, 0, nil, err
258:		}
259:		result, ok := value.(knowledge.Result)
260:		if !ok {
261:			return nil, 0, nil, fmt.Errorf("knowledge handle %q did not resolve to a section", handle)
262:		}
263:		results = append(results, result)
264:	}
265:	explicitCount := len(results)
266:	if request.Mode == "inspect" && len(handles) > 0 && strings.TrimSpace(request.Query) == "" {
267:		return results, len(results), nil, nil
268:	}
269:	query := strings.TrimSpace(request.Query)
270:	if query == "" {
271:		query = strings.TrimSpace(request.Anchor)
272:	}
273:	if query == "" && request.Mode == "orient" {
274:		query = "repository architecture overview entry points design rationale"
275:	}
276:	if query == "" {
277:		return results, len(results), nil, nil
278:	}
279:	topK := request.Limit
280:	if topK <= 0 {
281:		if request.Mode == "trace" {
282:			topK = 8
283:		} else {
284:			topK = 12
285:		}
286:	}
287:	if topK > 200 {
288:		topK = 200
289:	}
290:	candidateLimit := min(200, max(topK*4, topK))
291:	searchOptions := knowledge.SearchOptions{TopK: candidateLimit}
292:	if useDocumentVectors(request) && knowledgevector.Available(knowledgeState) {
293:		searchOptions.Vector = knowledgevector.Ranker{State: knowledgeState, Index: current, Endpoint: embedding.DefaultEndpoint}
294:	}
295:	searched, err := knowledge.Search(ctx, current, query, searchOptions)
296:	if err != nil {
297:		return nil, 0, nil, fmt.Errorf("search knowledge: %w", err)
298:	}
299:	compacted := compactKnowledgeResults(searched.Results)
300:	available := uniqueKnowledgeResultCount(results, compacted)
301:	if len(compacted) > topK {
302:		compacted = compacted[:topK]
303:	}
304:	results = appendUniqueKnowledge(results, compacted...)
305:	results = applyKnowledgePreviews(results, explicitCount, request.Detail)
306:	warnings := []string(nil)
307:	if searched.VectorError != "" {
308:		warnings = append(warnings, "knowledge vector ranking unavailable: "+searched.VectorError)
309:	}
310:	return results, available, warnings, nil
311:}
312:
313:func uniqueKnowledgeResultCount(existing, candidates []knowledge.Result) int {
314:	seen := make(map[string]bool, len(existing)+len(candidates))
315:	for _, result := range existing {
316:		seen[result.Handle] = true
317:	}
318:	for _, result := range candidates {
319:		seen[result.Handle] = true
320:	}
321:	return len(seen)
322:}
323:
324:func compactKnowledgeResults(results []knowledge.Result) []knowledge.Result {
325:	const maxTextBytes = 1200
326:	const maxCodeLinks = 8
327:	const maxReasons = 4
328:	compacted := append([]knowledge.Result(nil), results...)
329:	for index := range compacted {
330:		result := &compacted[index]
331:		result.Text = compactKnowledgeText(result.Text, maxTextBytes)
332:		if len(result.CodeLinks) > maxCodeLinks {
333:			result.CodeLinks = result.CodeLinks[:maxCodeLinks]
334:		}
335:		if len(result.Reasons) > maxReasons {
336:			result.Reasons = result.Reasons[:maxReasons]
337:		}
338:	}
339:	return compacted
340:}
341:
342:func compactKnowledgeText(text string, maxBytes int) string {
343:	text = strings.TrimSpace(text)
344:	if len(text) <= maxBytes {
345:		return text
346:	}
347:	cut := maxBytes
348:	for cut > 0 && !utf8.RuneStart(text[cut]) {
349:		cut--
350:	}
351:	text = strings.TrimSpace(text[:cut])
352:	if boundary := strings.LastIndexAny(text, "\n.!? "); boundary >= maxBytes/2 {
353:		text = strings.TrimSpace(text[:boundary])
354:	}
355:	return text + "…"
356:}
357:
358:func appendUniqueKnowledge(existing []knowledge.Result, values ...knowledge.Result) []knowledge.Result {
359:	seen := make(map[string]bool, len(existing)+len(values))
360:	for _, value := range existing {
361:		seen[value.Handle] = true
362:	}
363:	for _, value := range values {
364:		if !seen[value.Handle] {
365:			seen[value.Handle] = true
366:			existing = append(existing, value)
367:		}
368:	}
369:	return existing
370:}

