24:func sourceFingerprint(root string) (string, error) {
25:	if fingerprint, ok, err := gitFingerprint(root); ok || err != nil {
26:		return fingerprint, err
27:	}
28:	paths, err := walkedSourcePaths(root)
29:	if err != nil {
30:		return "", err
31:	}
32:	sort.Strings(paths)
33:	hash := sha256.New()
34:	for _, relative := range paths {
35:		if err := hashWorkingFile(hash, root, relative, "file"); err != nil {
36:			return "", err
37:		}
38:	}
39:	return "sha256:" + hex.EncodeToString(hash.Sum(nil)), nil
