42:func gitFingerprint(root string) (string, bool, error) {
43:	indexData, err := exec.Command("git", "-C", root, "ls-files", "-s", "-z").Output()
44:	if err != nil {
45:		return "", false, nil
46:	}
47:	hash := sha256.New()
48:	for _, raw := range strings.Split(string(indexData), "\x00") {
49:		metadata, relative, ok := strings.Cut(raw, "\t")
50:		if !ok || !fingerprintPath(relative) {
51:			continue
52:		}
53:		fields := strings.Fields(metadata)
54:		if len(fields) != 3 || fields[2] != "0" || strings.HasPrefix(fields[0], "120") {
55:			continue
56:		}
57:		path := filepath.Join(root, filepath.FromSlash(relative))
58:		if info, statErr := os.Lstat(path); statErr == nil && info.Size() > maxFingerprintFileBytes {
59:			continue
60:		}
61:		_, _ = io.WriteString(hash, "index\x00"+filepath.ToSlash(relative)+"\x00"+fields[1]+"\x00")
62:	}
63:
64:	changed, err := gitPathList(root, "diff", "--name-only", "-z")
65:	if err != nil {
66:		return "", true, err
67:	}
68:	untracked, err := gitPathList(root, "ls-files", "--others", "--exclude-standard", "-z")
69:	if err != nil {
70:		return "", true, err
71:	}
72:	for _, group := range []struct {
73:		name  string
74:		paths []string
75:	}{{"worktree", changed}, {"untracked", untracked}} {
76:		sort.Strings(group.paths)
77:		for _, relative := range group.paths {
78:			if !fingerprintPath(relative) {
79:				continue
80:			}
81:			if err := hashWorkingFile(hash, root, relative, group.name); err != nil {
82:				return "", true, err
83:			}
84:		}
85:	}
86:	return "sha256:" + hex.EncodeToString(hash.Sum(nil)), true, nil
87:}
