89:func gitPathList(root string, arguments ...string) ([]string, error) {
90:	data, err := exec.Command("git", append([]string{"-C", root}, arguments...)...).Output()
91:	if err != nil {
92:		return nil, err
93:	}
94:	seen := make(map[string]bool)
95:	result := make([]string, 0)
96:	for _, raw := range strings.Split(string(data), "\x00") {
97:		relative := filepath.ToSlash(strings.TrimSpace(raw))
98:		if relative != "" && !seen[relative] {
99:			seen[relative] = true
100:			result = append(result, relative)
101:		}
102:	}
103:	return result, nil
104:}
