106:func hashWorkingFile(hash io.Writer, root, relative, kind string) error {
107:	path := filepath.Join(root, filepath.FromSlash(relative))
108:	info, err := os.Lstat(path)
109:	if os.IsNotExist(err) {
110:		_, _ = io.WriteString(hash, kind+"\x00"+filepath.ToSlash(relative)+"\x00deleted\x00")
111:		return nil
112:	}
113:	if err != nil {
114:		return err
115:	}
116:	if !info.Mode().IsRegular() || info.Mode()&os.ModeSymlink != 0 || info.Size() > maxFingerprintFileBytes {
117:		return nil
118:	}
119:	file, err := os.Open(path)
120:	if err != nil {
121:		return err
122:	}
123:	defer file.Close()
124:	fileHash := sha256.New()
125:	if _, err := io.Copy(fileHash, file); err != nil {
126:		return err
127:	}
128:	_, _ = io.WriteString(hash, kind+"\x00"+filepath.ToSlash(relative)+"\x00")
129:	_, _ = hash.Write(fileHash.Sum(nil))
130:	return nil
131:}
