133:func gitSourcePaths(root string) ([]string, bool) {
134:	command := exec.Command("git", "-C", root, "ls-files", "-z", "--cached", "--others", "--exclude-standard")
135:	data, err := command.Output()
136:	if err != nil {
137:		return nil, false
138:	}
139:	seen := make(map[string]bool)
140:	paths := make([]string, 0, 256)
141:	for _, raw := range strings.Split(string(data), "\x00") {
142:		relative := filepath.ToSlash(strings.TrimSpace(raw))
143:		if relative == "" || !fingerprintPath(relative) || seen[relative] {
144:			continue
145:		}
146:		seen[relative] = true
147:		paths = append(paths, relative)
148:	}
149:	return paths, true
150:}
