152:func walkedSourcePaths(root string) ([]string, error) {
153:	paths := make([]string, 0, 256)
154:	err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
155:		if walkErr != nil {
156:			return walkErr
157:		}
158:		if path != root && entry.IsDir() && excludedDirectory(entry.Name()) {
