91:		if path != absoluteRoot {
92:			ignored, err := ignorePolicy.Ignored(path, entry.IsDir())
93:			if err != nil {
94:				return err
95:			}
96:			if ignored {
97:				if entry.IsDir() {
98:					return filepath.SkipDir
99:				}
100:				return nil
101:			}
102:		}
103:		if entry.IsDir() {
104:			return ignorePolicy.LoadDirectory(path)
105:		}
106:		if path == ignorePolicy.ControlFile() || !entry.Type().IsRegular() || !indexableFile(entry.Name()) {
107:			return nil
108:		}
109:		if !options.IncludeGenerated && generatedFileName(entry.Name()) {
110:			stats.GeneratedSkipped++
111:			return nil
112:		}
113:
114:		info, err := entry.Info()
115:		if err != nil {
116:			return err
117:		}
118:		if info.Size() > maxBytes {
119:			return nil
120:		}
121:
122:		content, err := os.ReadFile(path)
123:		if err != nil {
124:			return err
125:		}
126:		if bytes.IndexByte(content, 0) >= 0 {
127:			return nil
128:		}
129:		if !options.IncludeGenerated && generatedFileContent(entry.Name(), content) {
130:			stats.GeneratedSkipped++
131:			return nil
132:		}
133:
134:		relative, err := filepath.Rel(absoluteRoot, path)
135:		if err != nil {
136:			return err
137:		}
138:		relative = filepath.ToSlash(relative)
