33:func Build(root string, previous *Index, options BuildOptions) (Index, BuildStats, error) {
34:	absolute, err := filepath.Abs(root)
35:	if err != nil {
36:		return Index{}, BuildStats{}, fmt.Errorf("resolve repository root: %w", err)
37:	}
38:	policy, err := ignorepolicy.Load(absolute, options.IgnoreFile)
39:	if err != nil {
40:		return Index{}, BuildStats{}, err
41:	}
42:	excluded, err := normalizeExcludes(absolute, options.ExcludePaths)
43:	if err != nil {
44:		return Index{}, BuildStats{}, err
45:	}
46:	metadata := readRepoMetadata(absolute)
47:	old := make(map[string]Document)
48:	if previous != nil {
49:		for _, document := range previous.Documents {
50:			old[document.Path] = document
51:		}
52:	}
53:	maxBytes := options.MaxFileBytes
54:	if maxBytes <= 0 {
55:		maxBytes = defaultMaxBytes
56:	}
57:	seen := make(map[string]struct{})
58:	documents := make([]Document, 0)
59:	stats := BuildStats{}
60:	err = filepath.WalkDir(absolute, func(path string, entry fs.DirEntry, walkErr error) error {
61:		if walkErr != nil {
62:			return walkErr
63:		}
64:		if path != absolute && ignoredDirectory(entry, path, excluded) {
65:			if entry.IsDir() {
66:				return filepath.SkipDir
67:			}
68:			return nil
69:		}
70:		if path != absolute {
71:			ignored, ignoreErr := policy.Ignored(path, entry.IsDir())
72:			if ignoreErr != nil {
73:				return ignoreErr
74:			}
75:			if ignored {
76:				if entry.IsDir() {
77:					return filepath.SkipDir
78:				}
79:				return nil
80:			}
81:		}
82:		if entry.IsDir() {
83:			return policy.LoadDirectory(path)
84:		}
85:		if path == policy.ControlFile() || !entry.Type().IsRegular() {
86:			return nil
87:		}
88:		relative, relErr := filepath.Rel(absolute, path)
89:		if relErr != nil {
90:			return relErr
91:		}
92:		relative = filepath.ToSlash(relative)
93:		if !isKnowledgeFile(relative, entry.Name(), options.IncludeConfig) {
94:			return nil
95:		}
96:		info, infoErr := entry.Info()
97:		if infoErr != nil {
98:			return infoErr
99:		}
100:		if info.Size() > maxBytes {
101:			return nil
102:		}
103:		content, readErr := os.ReadFile(path)
104:		if readErr != nil {
105:			return readErr
106:		}
107:		if bytes.IndexByte(content, 0) >= 0 {
108:			return nil
109:		}
110:		seen[relative] = struct{}{}
111:		stats.Scanned++
112:		hash := hashBytes(content)
113:		if prior, ok := old[relative]; ok && prior.Hash == hash && prior.Size == info.Size() {
114:			prior.CommitID, prior.CommitTime = metadata.commit, metadata.time
115:			documents = append(documents, prior)
116:			stats.Reused++
117:			return nil
118:		}
119:		documents = append(documents, Document{
120:			ID: stableID("document", relative), Path: relative, Kind: classify(relative),
121:			Hash: hash, Size: info.Size(), CommitID: metadata.commit, CommitTime: metadata.time,
122:			Sections: extractSections(relative, string(content)),
123:		})
124:		stats.Updated++
125:		return nil
126:	})
127:	if err != nil {
128:		return Index{}, BuildStats{}, fmt.Errorf("walk knowledge documents: %w", err)
129:	}
130:	for path := range old {
131:		if _, ok := seen[path]; !ok {
132:			stats.Removed++
133:		}
134:	}
135:	catalog, catalogErr := buildCodeCatalog(absolute, options.IgnoreFile, excluded)
136:	if catalogErr != nil {
137:		return Index{}, BuildStats{}, catalogErr
