142:		}
143:	}
144:	sort.Slice(documents, func(i, j int) bool { return documents[i].Path < documents[j].Path })
145:	return Index{Version: FormatVersion, Root: absolute, GitCommit: metadata.commit, GitTime: metadata.time, Documents: documents}, stats, nil
146:}
