471:func TestEnsureSerializesConcurrentRefreshes(t *testing.T) {
472:	root := t.TempDir()
473:	writeSource(t, root, "package main\n")
474:	calls := make([]string, 0, 3)
475:	var mu sync.Mutex
476:	runner := fixtureRunner(t, root, &mu, &calls, false)
477:	var wait sync.WaitGroup
478:	statuses := make([]Status, 2)
479:	errorsFound := make([]error, 2)
480:	for i := range statuses {
481:		wait.Add(1)
482:		go func(index int) {
483:			defer wait.Done()
484:			statuses[index], errorsFound[index] = Ensure(context.Background(), Options{Root: root, Mode: RefreshIfNeeded, Run: runner})
485:		}(i)
486:	}
487:	wait.Wait()
488:	for i := range statuses {
489:		if errorsFound[i] != nil || !statuses[i].DeterministicQueryReady {
490:			t.Fatalf("concurrent refresh %d failed: status=%+v err=%v", i, statuses[i], errorsFound[i])
491:		}
492:	}
493:	if len(calls) != 4 {
494:		t.Fatalf("concurrent callers performed %d commands: %v", len(calls), calls)
495:	}
496:}
